/* "Sign in with Google" button: light (default) / dark themes per Google's branding guidelines
   (fill #FFFFFF/#131314, 1px stroke #747775/#8E918F, text #1F1F1F/#E3E3E3, 12px left padding,
   10px after the logo, 12px right padding). Font: Google Sans Medium where installed, then
   Roboto, then the system stack; no web font is fetched from Google. */
.gsi-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  height: 40px;
  min-width: 200px;
  max-width: 100%;
  padding: 0 12px;
  border: 1px solid var(--gsi-border);
  border-radius: 4px;
  background-color: var(--gsi-bg);
  color: var(--gsi-fg);
  font-family: "Google Sans", "Roboto", system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
  letter-spacing: 0.25px;
  cursor: pointer;
  transition: box-shadow 0.15s;
}

.gsi-button:hover {
  box-shadow: 0 1px 2px 0 rgb(60 64 67 / 30%), 0 1px 3px 1px rgb(60 64 67 / 15%);
}

.gsi-button > svg {
  width: 20px;
  height: 20px;
  margin-right: 10px;
  flex: none;
}

.gsi-button:focus-visible,
.focus-ring:focus-visible {
  outline: 2px solid var(--theme-secondary);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .animate-spin {
    animation: none;
  }
}

