  background-color: #450a0a;
  color: #fee2e2;
  border-color: #f87171;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .dark-error {
    background-color: #450a0a;
    color: #fee2e2;
    border-color: #f87171;
  }
}

