  --tone-grey-bg: #1e293b;
  --tone-grey-fg: #e2e8f0;
  --tone-grey-bd: #64748b;
}

.tone {
  background-color: var(--tone-bg);
  color: var(--tone-fg);
  border: 1px solid var(--tone-bd);
}

.tone-amber {
  --tone-bg: var(--tone-amber-bg);
  --tone-fg: var(--tone-amber-fg);
  --tone-bd: var(--tone-amber-bd);
}

.tone-green {
  --tone-bg: var(--tone-green-bg);
  --tone-fg: var(--tone-green-fg);
  --tone-bd: var(--tone-green-bd);
}

.tone-red {
  --tone-bg: var(--tone-red-bg);
  --tone-fg: var(--tone-red-fg);
  --tone-bd: var(--tone-red-bd);
}

.tone-grey {
  --tone-bg: var(--tone-grey-bg);
  --tone-fg: var(--tone-grey-fg);
  --tone-bd: var(--tone-grey-bd);
}

/* Thinking dots (motion is removed for prefers-reduced-motion). */
@keyframes chat-dot {
  0%, 80%, 100% { opacity: 0.25; }
  40% { opacity: 1; }
}

.chat-dot {
  display: inline-block;
  width: 0.375rem;
  height: 0.375rem;
  border-radius: 9999px;
  background-color: currentColor;
  animation: chat-dot 1.2s infinite ease-in-out;
}

.chat-dot:nth-child(2) { animation-delay: 0.2s; }
