  .chat-dot { animation: none; opacity: 0.6; }
  .chat-drawer { transition: none !important; }
}

/* Long unbroken text (e.g. a pasted URL) must wrap instead of overflowing a bubble. */
.chat-text {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
