import { describe, expect, it } from 'vitest'
import {
  attachmentKind,
  canSendMessage,
  downloadErrorMessage,
  extensionForMime,
  formatBytes,
  hasUploadError,
  isUploading,
  markRetrying,
  markUploaded,
