window.mk = {
  async png(name, color='#3b82f6', w=200, h=140) { const c = document.createElement('canvas'); c.width=w; c.height=h; const x=c.getContext('2d'); x.fillStyle=color; x.fillRect(0,0,w,h); x.fillStyle='#fff'; x.font='20px sans-serif'; x.fillText(name.slice(0,14),10,70); const b = await new Promise(r=>c.toBlob(r,'image/png')); return new File([b], name, {type:'image/png'}) },
  pdf(name, size=2000) { const head = '%PDF-1.4\n1 0 obj<<>>endobj\ntrailer<<>>\n%%EOF\n'; return new File([head + ' '.repeat(size)], name, {type:'application/pdf'}) },
  pick(files) { const input = document.querySelector('input[type=file]'); const dt = new DataTransfer(); files.forEach(f=>dt.items.add(f)); input.files = dt.files; input.dispatchEvent(new Event('change',{bubbles:true})) },
  sleep: ms => new Promise(r=>setTimeout(r,ms)),
  chips() { return [...document.querySelectorAll('ul[aria-label="Files to send with your message"] > li')].map(li=>li.innerText.replace(/\n/g,' | ')) },
  btn: t => [...document.querySelectorAll('button')].find(b=>b.textContent.trim()===t || b.getAttribute('aria-label')===t),
};
await mk.sleep(1500); mk.pick([await mk.png('blurry-scan.png','#64748b')]); await mk.sleep(1500); document.getElementById('chat-input').focus(); 'staged'

